import sys
import json
import numpy as np
import pandas as pd

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    df = pd.read_csv(sys.argv[1])

    facts = []

    # ---- Totals ----
    rev_tw = df['Revenue_TW'].sum(skipna=True)
    rev_lw = df['Revenue_LW'].sum(skipna=True)
    rev_ly = df['Revenue_LY'].sum(skipna=True)
    units_tw = df['Units_TW'].sum(skipna=True)
    units_lw = df['Units_LW'].sum(skipna=True)
    orders_tw = df['Orders_TW'].sum(skipna=True)
    orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw),
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": to_float(rev_ly),
        "formula": "sum(Revenue_LY)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw),
        "formula": "sum(Orders_LW)"
    })

    if rev_lw and not np.isnan(rev_lw) and rev_lw != 0:
        wow_total = (rev_tw - rev_lw) / rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly and not np.isnan(rev_ly) and rev_ly != 0:
        yoy_total = (rev_tw - rev_ly) / rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- Top 3 entities by Revenue_TW ----
    top_rev = df.dropna(subset=['Revenue_TW']).nlargest(3, 'Revenue_TW')
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW value from data"
        })

    # ---- Top 3 WoW gainers ----
    wow_df = df.dropna(subset=['WoW_Pct'])
    top_wow = wow_df.nlargest(3, 'WoW_Pct')
    for _, row in top_wow.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top 3 WoW decliners ----
    bottom_wow = wow_df.nsmallest(3, 'WoW_Pct')
    for _, row in bottom_wow.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top 3 YoY gainers ----
    yoy_df = df.dropna(subset=['YoY_Pct'])
    top_yoy = yoy_df.nlargest(3, 'YoY_Pct')
    for _, row in top_yoy.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # ---- Top 3 YoY decliners ----
    bottom_yoy = yoy_df.nsmallest(3, 'YoY_Pct')
    for _, row in bottom_yoy.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Ensure all numpy numbers are converted to native Python floats
    for f in facts:
        f['value'] = float(f['value'])

    print(json.dumps(facts[:25]))

if __name__ == "__main__":
    main()
